 if(!selected||(selected.group==='a'&&!sa?.display_ids.includes(+selected.id))||(selected.group==='b'&&!sb?.display_ids.includes(+selected.id)))selected=ba?{group:'a',...ba}:null;
 for(const [key,r] of [['A',A],['B',B]])$('spec'+key).textContent=r?`개체 ${r.setting.P} · 참조방향 ${((r.setting.p+1)*(r.setting.p+2))/2} · 변이 시도 평균 ${r.setting.lambda} · 평가예산 ${num(r.setting.budget)}`:'이 지도에서는 아직 NSGA-III를 실행하지 않았습니다.';
