  const cube=[];for(let x=0;x<2;x++)for(let y=0;y<2;y++)for(let z=0;z<2;z++)cube.push([x,y,z]);let pp=cube.map(p=>proj(...p));const mx=[Math.min(...pp.map(v=>v[0])),Math.max(...pp.map(v=>v[0]))],my=[Math.min(...pp.map(v=>v[1])),Math.max(...pp.map(v=>v[1]))];const scale=Math.min(680/(mx[1]-mx[0]),360/(my[1]-my[0]));const at=(x,y,z)=>{const p=proj(x,y,z);return[450+(p[0]-(mx[0]+mx[1])/2)*scale,235+(p[1]-(my[0]+my[1])/2)*scale]};
