  const origin=at(0,0,0);for(const [v,color]of [[[1,0,0],'#006a9f'],[[0,1,0],'#a74b00'],[[0,0,1],'#71359b']]){const q=at(...v);svg+=`<line x1="${origin[0]}" y1="${origin[1]}" x2="${q[0]}" y2="${q[1]}" stroke="${color}" stroke-width="4"/>`}
