  for(let i=0;i<=5;i++){let xx=80+i*148,yy=435-i*76;svg+=`<line class="grid" x1="80" y1="${yy}" x2="820" y2="${yy}"/><line class="grid" x1="${xx}" y1="55" x2="${xx}" y2="435"/><text class="tick" x="65" y="${yy+5}" text-anchor="end">${i*20}%</text><text class="tick" x="${xx}" y="460" text-anchor="middle">${cost?Math.round(xmax*i/5):i*20+'%'}</text>`}
