 s+=`<g clip-path="url(#clip-${prefix})"><circle cx="${xx(10000)}" cy="${yy(10000)}" r="${6000*scale}" fill="#e6edf2" fill-opacity=".35" stroke="#263f52" stroke-width="3.5" stroke-dasharray="12 8"/>`;
